(() => {'use strict';let saved=null;
 const words={seller:['مركز البائع','Seller center'],title:['محرر المتجر','Store editor'],visit:['زيارة المتجر','Visit storefront'],name:['اسم المتجر','Store name'],slug:['معرّف المتجر','Store identifier'],headline:['عنوان البانر','Cover headline'],description:['وصف المتجر','Store description'],location:['الموقع العام (مدينة، دولة)','Public location (city, country)'],save:['حفظ ونشر البيانات','Save & publish profile'],reload:['استعادة المحفوظ','Reload saved profile'],preview:['معاينة التغييرات','Preview changes'],previewNote:['تظهر التغييرات للزوار بعد الحفظ.','Visitors see your changes after you save.'],products:['المنتجات والصور والمخزون','Products, images & inventory'],delivery:['إعدادات التوصيل','Delivery settings'],allProducts:['جميع المنتجات','All products']};
 Object.assign(words,{logo:['شعار المتجر','Store logo'],cover:['صورة الغلاف','Cover image'],remove:['إزالة الصورة','Remove image'],MEDIA_INVALID:['اختر صورة JPG أو PNG حتى 5 ميغابايت.','Choose a JPG or PNG up to 5 MB.']});
 const w=window.BemoWorkspace.create(words,{seller:true,onReady:()=>w.run(load),onClear:()=>{saved=null;window.BemoBrand?.reset();w.$('profileForm').reset();w.$('publicLink').hidden=true;for(const id of ['storeName','storeSlug','storeHeadline','previewDescription','previewLocation'])w.$(id).textContent='';},onLanguage:()=>{if(saved)links();preview();}}),$=w.$;
 function links(){$('publicLink').href=w.url('store.html',{store:saved.slug});$('publicLink').hidden=false;$('deliveryLink').href=w.url('merchant.html')+'#sellerDelivery';}
 function preview(){$('storeName').textContent=$('storeTitle').value||'BEMO';$('storeMark').textContent=[...($('storeTitle').value||'B')].slice(0,2).join('');$('storeSlug').textContent=$('slug').value?'@'+$('slug').value:'';$('storeHeadline').textContent=$('headline').value;$('previewDescription').textContent=$('description').value;$('previewLocation').textContent=$('locationLabel').value;window.BemoBrand?.preview(saved);}
 function fill(s){window.BemoBrand?.reset();saved=s;$('storeTitle').value=s.title;$('slug').value=s.slug;$('description').value=s.description;$('headline').value=s.headline;$('locationLabel').value=s.location_label;links();preview();}
 async function load(request){fill(await request('bemo_store_workspace'));}
 $('profileForm').addEventListener('input',preview);$('reload').addEventListener('click',()=>w.run(load));$('profileForm').addEventListener('submit',e=>{e.preventDefault();if(!saved)return;const args={title:$('storeTitle').value.trim(),description:$('description').value.trim(),location_label:$('locationLabel').value.trim(),headline:$('headline').value.trim(),expected_version:saved.profile_version};w.run(async request=>{if(window.BemoBrand){args.images=await window.BemoBrand.upload();fill(await request('bemo_publish_store_profile',args));}else fill(await request('bemo_save_store_profile',args));},'saving');});w.start();
})();
